dir$s12.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$s12DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$s12DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_kien].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  if (p.options._sale_lock_master == 1) p.setDisabled(['ma_kh', 'ngay_ct', 'ma_nt'], dis);
}
function dir$s12HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
}
function dir$s12HiddenColumnByTran(p){
  var gd = p.valForm('ma_gd');
	if(gd == 'KC') {
		p.setDisabled(['ma_so_thue','ten_kh','ten_kh2','dia_chi','nguoi_lh'], true);
		p.setInvisible('ma_kh', false);

		if(p.options.action == "NEW") {
			p.valForm('ma_kh', "" , true);
			p.valForm('ten_kh', "" , true);
			p.valForm('ten_kh2', "" , true);
			p.valForm('ma_so_thue', "" , true);
			p.valForm('dia_chi', "" , true);
			p.valForm('nguoi_lh', "" , true);
			p.valForm('dien_thoai', "" , true);
		}
		else {
			p.setDisabled('ma_gd', true);
		}
	}
	else {
		p.setInvisible('ma_kh', true);
		p.setDisabled(['ma_so_thue','ten_kh','ten_kh2','dia_chi','nguoi_lh'], false);

		if(p.options.action == "NEW") {
			p.valForm('ma_kh', "" , true);
			p.valForm('ten_kh', "" , true);
			p.valForm('ten_kh2', "" , true);
			p.valForm('ma_so_thue', "" , true);
			p.valForm('dia_chi', "" , true);
			p.valForm('nguoi_lh', "" , true);
			p.valForm('dien_thoai', "" , true);

		}
		else {
			p.setDisabled('ma_gd', true);
		}
	}

}
function dir$s12DisabledDT(p){
var gd = p.valForm('ma_gd');
var kh = p.valForm('ma_kh');   
	if (kh != "" && gd == 'KC') {
		p.request('ma_kh_request', '', ['ma_kh', 'ngay_ct', 'ma_nt'])
		return;
	}
	if(kh == "" && gd == 'KC'){
		p.valForm('ten_kh', "" , true);
		p.valForm('ten_kh2', "" , true);
		p.valForm('ma_so_thue', "" , true);
		p.valForm('dia_chi', "" , true);
		p.valForm('nguoi_lh', "" , true);
		p.valForm('dien_thoai', "" , true);

		return;
	}
}
